"""Join original route telemetry to cited non-visual facts without legal inference."""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

COUNT = 600
REQUIRED_FACT_SOURCES = ('weight', 'district', 'truck_route', 'civil_clock', 'permit')


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _rows(path: Path) -> list[dict]:
    if not path.is_file():
        raise ValueError('Missing required source: ' + path.name)
    values = [json.loads(line) for line in path.read_text().splitlines()]
    if len(values) != COUNT:
        raise ValueError('Original route trace requires 600 frame rows')
    return values


def load(attempt: Path, case_id: str) -> dict:
    attempt = Path(attempt)
    for name in ('authority-context.json', 'capture-seal.json'):
        if not (attempt / name).is_file():
            raise ValueError('Missing required source: ' + name)
    context = json.loads((attempt / 'authority-context.json').read_text())
    seal = json.loads((attempt / 'capture-seal.json').read_text())
    if context.get('case_id') != case_id or context.get('source_kind') not in ('synthetic_native_sample', 'original_review_packet'):
        raise ValueError('Source context case or kind differs')
    terms = ('ru.truck', 'ru.commercial_motor_vehicle', 'kin.extent', 'st.roadway', 'dev.regulatory_sign', 'env.civil_time', 'drv.condition_in_effect', 'kin.velocity')
    if any(not isinstance(context.get(term), dict) or not context[term] for term in terms):
        raise ValueError('Missing authored instance context')
    refs = context.get('authority_refs')
    if not isinstance(refs, dict) or set(refs) != set(REQUIRED_FACT_SOURCES):
        raise ValueError('Every factual authority needs an exact source reference')
    for key, ref in refs.items():
        if not isinstance(ref, dict) or not isinstance(ref.get('path'), str) or not isinstance(ref.get('sha256'), str):
            raise ValueError('Malformed authority source reference: ' + key)
        path = attempt / ref['path']
        if path.resolve().parent != attempt.resolve() or not path.is_file():
            raise ValueError('Missing required source: ' + ref['path'])
        if sha(path) != ref['sha256']:
            raise ValueError('Changed authority source: ' + key)
    rows = _rows(attempt / 'original-route-rows.jsonl')
    frames = _rows(attempt / 'video_frames.jsonl')
    if seal.get('case_id') != case_id:
        raise ValueError('Capture seal case differs')
    protected = ('authority-context.json', 'original-route-rows.jsonl', 'video_frames.jsonl')
    hashes = seal.get('sha256')
    if not isinstance(hashes, dict) or any(hashes.get(name) != sha(attempt / name) for name in protected):
        raise ValueError('Original source seal differs')
    last_time = -math.inf
    for index, (row, frame) in enumerate(zip(rows, frames)):
        if row.get('case_id') != case_id or row.get('source_kind') != 'original_native_pose':
            raise ValueError('Original route row identity differs')
        if row.get('video_frame') != index or frame.get('video_frame') != index or row.get('native_frame') != frame.get('native_frame'):
            raise ValueError('Native route/frame join differs')
        time_s = row.get('time_s')
        if type(time_s) not in (int, float) or not math.isfinite(time_s) or time_s <= last_time or abs(time_s - frame.get('time_s', -1)) > .001:
            raise ValueError('Native time join differs')
        last_time = time_s
        if type(row.get('road_id')) is not int or type(row.get('ego_speed_mps')) not in (int, float) or not math.isfinite(row['ego_speed_mps']) or row['ego_speed_mps'] < 0:
            raise ValueError('Original road or movement source differs')
        if any(type(row.get(key)) not in (int, float) or not math.isfinite(row[key]) for key in ('ego_x_m', 'ego_y_m')):
            raise ValueError('Original position source differs')
        extent = row.get('vehicle_half_extent_m')
        if not isinstance(extent, list) or len(extent) != 2 or any(type(value) not in (int, float) or not math.isfinite(value) or value <= 0 for value in extent):
            raise ValueError('Original body extent source differs')
    return {'format': 'c394566-source-join-v1', 'case_id': case_id,
            'source_kind': context['source_kind'], 'context': context,
            'rows': rows, 'frame_count': COUNT,
            'source_hashes': {name: sha(attempt / name) for name in protected},
            'authority_hashes': {key: ref['sha256'] for key, ref in refs.items()},
            'original_authority_reviewed': False, 'physical_or_legal_accepted': False}

"""Source-hashed factual measurements for LVMC 11.48.050.

This evaluates the observed prerequisites separately. It does not establish that
an administrative document is authentic or return a legal verdict.
"""
from __future__ import annotations

from datetime import datetime, time
import hashlib
import json
import math
from zoneinfo import ZoneInfo


def night_status(instant: datetime) -> str:
    local = instant.astimezone(ZoneInfo("America/Los_Angeles"))
    clock = local.time().replace(tzinfo=None)
    if clock in (time(19), time(6)):
        return "endpoint_unresolved"
    return "inside" if clock > time(19) or clock < time(6) else "outside"


def measure(source: bytes, expected_sha256: str) -> dict:
    digest = hashlib.sha256(source).hexdigest()
    if digest != expected_sha256:
        raise ValueError("source packet hash mismatch")
    facts = json.loads(source)
    if facts.get("source_kind") not in ("synthetic_native_sample", "original_review_packet"):
        raise ValueError("source kind missing")
    weight = facts.get("unladen_weight_lb")
    if type(weight) not in (int, float) or not math.isfinite(weight) or weight < 0:
        raise ValueError("vehicle-specific unladen weight source missing")
    if not isinstance(facts.get("weight_source_ref"), str) or not facts["weight_source_ref"]:
        raise ValueError("unladen weight provenance missing")
    if facts.get("district") not in ("residence", "other", "unverified"):
        raise ValueError("district classification source missing")
    if facts.get("truck_route") not in (True, False, None):
        raise ValueError("truck-route designation source missing")
    if not isinstance(facts.get("route_source_ref"), str) or not facts["route_source_ref"]:
        raise ValueError("truck-route authority provenance missing")
    stamp = facts.get("civil_timestamp")
    if not isinstance(stamp, str):
        raise ValueError("local civil time source missing")
    try:
        instant = datetime.fromisoformat(stamp)
    except ValueError as error:
        raise ValueError("invalid local civil timestamp") from error
    if instant.tzinfo is None or instant.utcoffset() is None:
        raise ValueError("civil time requires UTC offset")
    speed = facts.get("observed_speed_mps")
    if type(speed) not in (int, float) or not math.isfinite(speed) or speed < 0:
        raise ValueError("original movement source missing")
    if facts.get("written_permit_status") not in ("absent", "present", "unverified"):
        raise ValueError("written permit status source missing")
    return {"format": "c394566-restriction-facts-v1", "source_sha256": digest,
            "vehicle_over_8000_lb": weight > 8000,
            "night_window": night_status(instant),
            "residence_district": None if facts["district"] == "unverified" else facts["district"] == "residence",
            "non_truck_route": None if facts["truck_route"] is None else not facts["truck_route"],
            "observed_movement": speed > 0,
            "written_permit_status": facts["written_permit_status"],
            "permit_scope_and_conditions_verified": False,
            "legal_result": None,
            "limitations": ["clock endpoints preserved as unresolved",
                            "route, district, weight, and permit documents require original independent review",
                            "written permit identity, routes, times and conditions are not decided here"]}

"""Finalize sealed restriction source facts without asserting legal or physical acceptance."""
import argparse
import hashlib
import json
from pathlib import Path

from route_measurement import evaluate

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')


def sha(path):
    path = Path(path)
    if not path.is_file():
        raise ValueError('Missing required source: ' + path.name)
    return hashlib.sha256(path.read_bytes()).hexdigest()


def measure_activation(facts):
    return {'vehicle_over_8000_lb': facts['vehicle_over_8000_lb'],
            'residence_district': facts['residence_district'],
            'non_truck_route': facts['non_truck_route']}


def measure_night_window(facts):
    return {'night_window': facts['night_window'],
            'clock_endpoint_unresolved': facts['night_window'] == 'endpoint_unresolved'}


def measure_night_exit(facts):
    return {'night_window': facts['night_window'],
            'six_am_endpoint_unresolved': facts['night_window'] == 'endpoint_unresolved'}


def measure_movement(facts):
    return {'observed_movement': facts['observed_movement']}


def measure_permit(facts):
    return {'written_permit_status': facts['written_permit_status'],
            'permit_scope_and_conditions_verified': False}


def measure_reviewed_scope(facts):
    return {'restricted_street_source_required': True,
            'residence_district': facts['residence_district'],
            'non_truck_route': facts['non_truck_route'],
            'observed_movement': facts['observed_movement']}


def write_channel(path, frame_map, rows, name, facts):
    with path.open('x') as stream:
        for frame, row in zip(frame_map, rows):
            value = ({'road_id': row['road_id'], 'x_m': row.get('ego_x_m'),
                      'y_m': row.get('ego_y_m'), 'speed_mps': row['ego_speed_mps']}
                     if name == 'ego_pose' else
                     {'road_id': row['road_id'], 'speed_mps': row['ego_speed_mps'],
                      'vehicle_over_8000_lb': facts['vehicle_over_8000_lb'],
                      'night_window': facts['night_window'],
                      'residence_district': facts['residence_district'],
                      'non_truck_route': facts['non_truck_route'],
                      'written_permit_status': facts['written_permit_status'],
                      'permit_scope_and_conditions_verified': False})
            stream.write(json.dumps({'time_s': frame['time_s'], 'value': value}, allow_nan=False)+'\n')


def finalize(attempt, output):
    attempt, output = Path(attempt), Path(output)
    config = json.loads((attempt/'config.json').read_text())
    case_id = config['case_id']
    joined = evaluate(attempt, case_id)
    facts = joined['factual_measurements']
    for name in ('trace.jsonl', *[x+'.mkv' for x in CAMERAS]):
        sha(attempt/name)
    mapping = [json.loads(line) for line in (attempt/'video_frames.jsonl').read_text().splitlines()]
    channel_dir = attempt/'channels'; channel_dir.mkdir(exist_ok=True)
    evidence = []
    for channel in config['recording_description']['channels']:
        name = channel['name'];reference = 'channels/'+name+'.jsonl'
        write_channel(attempt/reference, mapping, joined['rows'], name, facts)
        evidence.append({'name': name, 'unit': channel['unit'], 'reference': reference})
    for item in config['recording_description'].get('context_inputs', []):
        evidence.append({'name': item['name'], 'unit': item['unit'],
                         'reference': 'authority-context.json'})
    requested = config.get('requested_motion') != 'stationary'
    motion = facts['observed_movement']
    target = {'target': 'observed original vehicle movement in requested phase',
              'requested': requested, 'measured': motion,
              'method': 'sealed original Native speed/frame source join',
              'tolerance': 0, 'matched': requested == motion,
              'physical_cause_confirmed': False,
              'cause_evidence': ['original-route-rows.jsonl', 'video_frames.jsonl']}
    result = {'case_id': case_id, 'measured_values': {'restriction_facts': facts},
              'target_checks': [target], 'setup_confirmed': False,
              'behavior_attempted': False, 'maneuver_completed': False,
              'termination_reason': 'Source-joined facts measured; original authority and physical review pending',
              'physical_failure_flags': ['original_authority_and_physical_review_pending'],
              'trace_reference': 'trace.jsonl',
              'video_references': [x+'.mkv' for x in CAMERAS],
              'video_frame_map_reference': 'video_frames.jsonl',
              'recording_description': config['recording_description'],
              'recording_evidence': evidence, 'realized_observables': {},
              'physical_acceptance_claimed': False, 'legal_verdict_claimed': False}
    from worker_exchange.native_output import physical_result, write_result
    write_result(attempt, physical_result(attempt, result))
    sources = {'authority-context.json': sha(attempt/'authority-context.json'),
               'original-route-rows.jsonl': sha(attempt/'original-route-rows.jsonl'),
               'video_frames.jsonl': sha(attempt/'video_frames.jsonl'),
               'capture-seal.json': sha(attempt/'capture-seal.json')}
    for key, ref in joined['context']['authority_refs'].items():
        sources[ref['path']] = sha(attempt/ref['path'])
    measurements = {}
    for key, method in (('activation_facts', measure_activation),
                        ('night_window_facts', measure_night_window),
                        ('night_exit_facts', measure_night_exit),
                        ('movement_facts', measure_movement),
                        ('permit_facts', measure_permit),
                        ('reviewed_scope_facts', measure_reviewed_scope)):
        measurements[key] = {'value': method(facts), 'method': method.__name__,
                             'sources': sources}
    report = {'format': 'worker-analysis-report', 'case_id': case_id,
              'measurements': measurements, 'source_complete': True,
              'diagnostic_fixture': joined['source_kind'] == 'synthetic_native_sample',
              'original_authority_reviewed': False,
              'physical_or_legal_acceptance': False}
    output.write_text(json.dumps(report, indent=2, allow_nan=False)+'\n')
    return report


if __name__ == '__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',required=True)
    parser.add_argument('--output',required=True);args=parser.parse_args()
    print(json.dumps(finalize(args.attempt,args.output),sort_keys=True,allow_nan=False))
